#include <stdio.h>

typedef struct Node {
    int data;
    struct Node *next;
} Node;

// 朴素法：先求长度，再走到正数第n-k+1个结点
Node* kthByLength(Node* head, int k) {
    if (!head || k <= 0) return NULL;
    int n = 0;
    for (Node* p = head->next; p; p = p->next) n++;
    if (k > n) return NULL;           // 长度不够
    Node* p = head->next;
    for (int i = 0; i < n - k; i++) p = p->next;
    return p;
}

// 快慢指针法：fast先走k步，随后两个指针同步走
Node* kthByTwoPointers(Node* head, int k) {
    if (!head || k <= 0) return NULL;
    Node *fast = head->next, *slow = head->next;
    for (int i = 0; i < k; i++) {
        if (!fast) return NULL;       // k超出链表长度
        fast = fast->next;            // 保持fast领先k步
    }
    while (fast) {
        fast = fast->next;
        slow = slow->next;            // 两者距离仍为k
    }
    return slow;                      // fast到NULL时slow恰好倒数第k
}

int main(void) {
    Node n5 = {5, NULL}, n4 = {4, &n5}, n3 = {3, &n4};
    Node n2 = {2, &n3}, n1 = {1, &n2}, head = {0, &n1};
    Node *a = kthByLength(&head, 2);
    Node *b = kthByTwoPointers(&head, 2);
    printf("长度法=%d，快慢指针=%d\n", a ? a->data : -1, b ? b->data : -1);
    return 0;
}

