#include <stdio.h>

// 判断相邻两个字符能否抵消
int match(char a, char b) {
    return (a == '(' && b == ')') ||
           (a == '[' && b == ']') ||
           (a == '{' && b == '}');
}

// 朴素法：反复删除相邻的一对合法括号
// 注意：这个函数会修改原字符串 s
int valid(char s[]) {
    int n = 0;
    while (s[n] != '\0') n++;  // 手动求字符串长度

    while (n >= 2) {
        int found = 0;         // 这一轮有没有删掉一对

        for (int i = 0; i < n - 1; i++) {
            if (match(s[i], s[i + 1])) {
                // 把后面的字符左移2位，包括结束符'\0'
                for (int j = i; j <= n - 2; j++)
                    s[j] = s[j + 2];

                n -= 2;       // 逻辑长度缩小两个字符
                found = 1;
                break;        // 删除后从头重新扫描
            }
        }

        if (!found) break;     // 找不到可抵消的一对，停止
    }
    return n == 0;            // 全部消去，才是合法括号序列
}

int main(void) {
    char s[] = "([{}])";      // 可修改的字符数组
    printf("是否合法：%s\n", valid(s) ? "是" : "否");
    return 0;
}

