#include <stdio.h>

#define MAXN 1000

// 顺序栈判断括号是否配对
int valid(const char s[]) {
    char stack[MAXN];         // 最坏情况全部是左括号
    int top = -1;             // -1 表示空栈

    for (int i = 0; s[i] != '\0'; i++) {
        char c = s[i];

        if (c == '(' || c == '[' || c == '{') {
            // 左括号入栈，等待右括号匹配
            if (top == MAXN - 1) return 0;
            stack[++top] = c;
        } else {
            // 题目保证字符只包括六种括号
            if (top == -1) return 0; // 没有左括号可匹配

            char left = stack[top--]; // 弹出最近的左括号
            if (!((left == '(' && c == ')') ||
                  (left == '[' && c == ']') ||
                  (left == '{' && c == '}')))
                return 0;          // 类型不匹配
        }
    }

    return top == -1;          // 不得有剩余未匹配的左括号
}

int main(void) {
    char s[] = "([{}])";
    printf("是否合法：%s\n", valid(s) ? "是" : "否");
    return 0;
}

