#include <stdio.h>

// 变式：只含()的字符串，最少插入几个括号才合法
int minInsertions(const char s[]) {
    int left = 0;   // 尚未匹配的左括号数量
    int add = 0;    // 必须补充的左括号数量

    for (int i = 0; s[i] != '\0'; i++) {
        if (s[i] == '(') {
            left++;            // 新的左括号尚待匹配
        } else {                // 遇到右括号
            if (left > 0) {
                left--;        // 匹配一个已有的左括号
            } else {
                add++;         // 没有左括号，只能补一个 '('
            }
        }
    }
    return add + left; // 剩余左括号需要补同样多的 ')'
}

int main(void) {
    char s[] = "())(";
    printf("最少插入：%d\n", minInsertions(s)); // 输出2
    return 0;
}
